",\u000a            "required": true,\u000a            "description": "並び順。new は作成日時の降順、popular はコメント数の降順。",\u000a            "schema": {\u000a              "type": "string"\u000a            }\u000a          },\u000a          {\u000a            "name": "page",\u000a            "in": "query",\u000a            "required": true,\u000a            "description": "1始まりのページ番号。",\u000a            "schema": {\u000a              "type": "integer"\u000a            }\u000a          },\u000a          {\u000a            "name": "pageSize",\u000a            "in": "query",\u000a            "required": true,\u000a            "description": "1ページあたりの件数。",\u000a            "schema": {\u000a              "type": "integer"\u000a            }\u000a          }\u000a        ]\u000a      },\u000a      "post": {\u000a        "operationId": "createThread",\u000a        "summary": "新規スレッドを投稿する",\u000a        "description": "タイトルと本文を受け取り、匿名の共有スレッドとして保存する。author_nameはDBの既定値を使用する。投稿後の編集・削除は対象外とする。",\u000a        "tags": [\u000a          "threads"\u000a        ],\u000a        "requestBody": {\u000a          "required": true,\u000a          "description": "新規スレッドのJSON本文",\u000a          "content": {\u000a            "application/json": {\u000a              "schema": {\u000a                "$ref": "#/components/schemas/CreateThreadRequest"\u000a              }\u000a            }\u000a          }\u000a        },\u000a        "responses": {\u000a          "201": {\u000a            "description": "スレッドを作成した",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ThreadDetailResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "400": {\u000a            "description": "タイトルまたは本文が空、または入力形式が不正",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "500": {\u000a            "description": "スレッドの保存に失敗",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          }\u000a        }\u000a      }\u000a    },\u000a    "/threads/{threadId}": {\u000a      "get": {\u000a        "operationId": "getThread",\u000a        "summary": "スレッド詳細を取得する",\u000a        "description": "スレッド本文と公開コメントを取得する。コメントは作成日時の昇順で返す。",\u000a        "tags": [\u000a          "threads"\u000a        ],\u000a        "responses": {\u000a          "200": {\u000a            "description": "スレッド詳細とコメントを返す",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ThreadDetailResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "400": {\u000a            "description": "threadIdが不正",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "404": {\u000a            "description": "指定したスレッドが存在しない",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "500": {\u000a            "description": "スレッド詳細の取得に失敗",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          }\u000a        },\u000a        "parameters": [\u000a          {\u000a            "name": "threadId",\u000a            "in": "path",\u000a            "required": true,\u000a            "description": "取得対象スレッドのID。",\u000a            "schema": {\u000a              "type": "integer"\u000a            }\u000a          }\u000a        ]\u000a      }\u000a    },\u000a    "/threads/{threadId}/comments": {\u000a      "post": {\u000a        "operationId": "createComment",\u000a        "summary": "スレッドにコメントを投稿する",\u000a        "description": "指定したスレッドに匿名の公開コメントを追加する。コメント投稿後の編集・削除は対象外とする。",\u000a        "tags": [\u000a          "comments"\u000a        ],\u000a        "requestBody": {\u000a          "required": true,\u000a          "description": "新規コメントのJSON本文",\u000a          "content": {\u000a            "application/json": {\u000a              "schema": {\u000a                "$ref": "#/components/schemas/CreateCommentRequest"\u000a              }\u000a            }\u000a          }\u000a        },\u000a        "responses": {\u000a          "201": {\u000a            "description": "コメントを作成した",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/CommentResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "400": {\u000a            "description": "本文が空、または入力形式が不正",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "404": {\u000a            "description": "指定したスレッドが存在しない",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          },\u000a          "500": {\u000a            "description": "コメントの保存に失敗",\u000a            "content": {\u000a              "application/json": {\u000a                "schema": {\u000a                  "$ref": "#/components/schemas/ErrorResponse"\u000a                }\u000a              }\u000a            }\u000a          }\u000a        },\u000a        "parameters": [\u000a          {\u000a            "name": "threadId",\u000a            "in": "path",\u000a            "required": true,\u000a            "description": "コメント先スレッドのID。",\u000a            "schema": {\u000a              "type": "integer"\u000a            }\u000a          }\u000a        ]\u000a      }\u000a    }\u000a  },\u000a  "components": {\u000a    "schemas": {\u000a      "CreateThreadRequest": {\u000a        "type": "object",\u000a        "description": "新規スレッド投稿のJSON body。titleとbodyは必須の非空文字列。",\u000a        "properties": {\u000a          "title": {\u000a            "type": "string",\u000a            "description": "スレッドタイトル。空文字不可。"\u000a          },\u000a          "body": {\u000a            "type": "string",\u000a            "description": "スレッド本文。空文字不可。"\u000a          }\u000a        },\u000a        "required": [\u000a          "title",\u000a          "body"\u000a        ]\u000a      },\u000a      "CreateCommentRequest": {\u000a        "type": "object",\u000a        "description": "コメント投稿のJSON body。bodyは必須の非空文字列。",\u000a        "properties": {\u000a          "body": {\u000a            "type": "string",\u000a            "description": "コメント本文。空文字不可。"\u000a          }\u000a        },\u000a        "required": [\u000a          "body"\u000a        ]\u000a      },\u000a      "ThreadSummary": {\u000a        "type": "object",\u000a        "description": "スレッド一覧の主要レコード。",\u000a        "properties": {\u000a          "id": {\u000a            "type": "integer",\u000a            "description": "自動生成されるスレッドID。"\u000a          },\u000a          "title"