\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ThreadDetailResponse\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"タイトルまたは本文が空、または入力形式が不正\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"スレッドの保存に失敗\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    \"/threads/{threadId}\": {\n      \"get\": {\n        \"operationId\": \"getThread\",\n        \"summary\": \"スレッド詳細を取得する\",\n        \"description\": \"スレッド本文と公開コメントを取得する。コメントは作成日時の昇順で返す。\",\n        \"tags\": [\n          \"threads\"\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"スレッド詳細とコメントを返す\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ThreadDetailResponse\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"threadIdが不正\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"description\": \"指定したスレッドが存在しない\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          },\n          \"500\": {\n            \"description\": \"スレッド詳細の取得に失敗\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          }\n        },\n        \"parameters\": [\n          {\n            \"name\": \"threadId\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"description\": \"取得対象スレッドのID。\",\n            \"schema\": {\n              \"type\": \"integer\"\n            }\n          }\n        ]\n      }\n    },\n    \"/threads/{threadId}/comments\": {\n      \"post\": {\n        \"operationId\": \"createComment\",\n        \"summary\": \"スレッドにコメントを投稿する\",\n        \"description\": \"指定したスレッドに匿名の公開コメントを追加する。コメント投稿後の編集・削除は対象外とする。\",\n        \"tags\": [\n          \"comments\"\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"description\": \"新規コメントのJSON本文\",\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/CreateCommentRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"201\": {\n            \"description\": \"コメントを作成した\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/CommentResponse\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"description\": \"本文が空、または入力形式が不正\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ErrorResponse\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"description\": \"指定したスレッドが存在しない\",\n            \"content\