le\": {\n            \"type\": \"string\",\n            \"description\": \"スレッドタイトル。\"\n          },\n          \"author_name\": {\n            \"type\": \"string\",\n            \"description\": \"投稿者名。ログイン不要のため既定値は匿名。\"\n          },\n          \"created_at\": {\n            \"type\": \"string\",\n            \"description\": \"ISO 8601形式の作成日時。\"\n          },\n          \"comment_count\": {\n            \"type\": \"integer\",\n            \"description\": \"紐づくコメント数。人気順の基準に使用する派生値。\"\n          }\n        },\n        \"required\": [\n          \"id\",\n          \"title\",\n          \"author_name\",\n          \"created_at\",\n          \"comment_count\"\n        ]\n      },\n      \"ThreadDetail\": {\n        \"type\": \"object\",\n        \"description\": \"スレッド詳細と公開コメント。\",\n        \"properties\": {\n          \"id\": {\n            \"type\": \"integer\",\n            \"description\": \"スレッドID。\"\n          },\n          \"title\": {\n            \"type\": \"string\",\n            \"description\": \"スレッドタイトル。\"\n          },\n          \"body\": {\n            \"type\": \"string\",\n            \"description\": \"スレッド本文。\"\n          },\n          \"author_name\": {\n            \"type\": \"string\",\n            \"description\": \"投稿者名。\"\n          },\n          \"created_at\": {\n            \"type\": \"string\",\n            \"description\": \"ISO 8601形式の作成日時。\"\n          },\n          \"comments\": {\n            \"type\": \"array\",\n            \"items\": {},\n            \"description\": \"コメント配列。created_at昇順、同値時はid昇順。\"\n          }\n        },\n        \"required\": [\n          \"id\",\n          \"title\",\n          \"body\",\n          \"author_name\",\n          \"created_at\",\n          \"comments\"\n        ]\n      },\n      \"CommentResponse\": {\n        \"type\": \"object\",\n        \"description\": \"作成または取得したコメント。\",\n        \"properties\": {\n          \"id\": {\n            \"type\": \"integer\",\n            \"description\": \"自