INSERT INTO "design_questionnaire_question_sets" ("id", "created_at", "updated_at", "session_id", "sequence", "questionnaire_json", "raw_output", "validation_status") VALUES('02ec7b58-25ab-4cf0-abd0-cd8b7dc47898',1783667595,1783667595,'432ac425-fdec-43de-9438-eabe6f5722cc',1,'{"version":1,"source":{"taskId":"9064d7c6-d0e1-42e9-b8ee-bd4e1ba21c82","repositoryId":"0d29c1f1-f213-44d7-9f03-95296df52e0c","sourceKind":"plan_mode_intake","blueprintMessageId":null},"title":"BBS 初回仕様確認","summary":"実装前に決めたい項目を選択式で確認します。","questionSets":[{"id":"choice-form","title":"BBS 初回仕様確認","category":"実装前確認","purpose":"実装に入る前に、未決定の仕様判断を選択式で確定します。","questions":[{"id":"q1","topic":"Question 1","question":"初回実装で優先する閲覧導線はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q1-o1","label":"スレッド一覧から詳細・コメントへ進む最小構成","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o2","label":"一覧と詳細を同一画面で確認する構成","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o3","label":"一覧・詳細に加えてカテゴリ別の閲覧も含める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-1"},{"id":"q2","topic":"Question 2","question":"初回実装に含める投稿単位はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q2-o1","label":"スレッド投稿のみ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o2","label":"スレッド投稿とコメント返信","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o3","label":"スレッド投稿・コメント返信・コメントへの返信","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-2"},{"id":"q3","topic":"Question 3","question":"投票機能の初期範囲はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q3-o1","label":"今回は含めない","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o2","label":"投稿への賛成票・反対票のみ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o3","label":"投稿とコメントへの賛成票・反対票","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o4","label":"賛成票のみ","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-3"},{"id":"q4","topic":"Question 4","question":"一覧の並び替えと追加読み込みはどの範囲にしますか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q4-o1","label":"新着順の固定表示のみ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o2","label":"新着順・人気順を切り替え、ページングする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o3","label":"新着順・人気順を切り替え、無限スクロールする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o4","label":"今回は一覧の並び替えを後続対応にする","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-4"},{"id":"q5","topic":"Question 5","question":"todolist の実装に使う技術スタックはどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q5-o1","label":"Hono + React/Vite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o2","label":"Python/FastAPI + React/Vite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o3","label":"API only","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o4","label":"RAG を含む構成","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o5","label":"既存構成を調査してから決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-5"},{"id":"q6","topic":"Question 6","question":"投稿・コメント・投票の保存先はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q6-o1","label":"SQLite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o2","label":"PostgreSQL","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o3","label":"PostgreSQL + pgvector","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o4","label":"Turso/libSQL","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o5","label":"DBなし・後続決定","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-6"},{"id":"q7","topic":"Question 7","question":"ユーザー、投稿、コメントのデータ所有境界はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q7-o1","label":"ユーザー識別なしで、BBS 全体の共有データとして扱う","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o2","label":"ユーザー識別を持ち、自分の投稿・コメントだけ編集削除できる","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o3","label":"ユーザー識別を持ち、自分の投稿・コメントに加えて管理者操作も持つ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q7-o4","label":"所有境界は後続の認証仕様と合わせて決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-7"},{"id":"q8","topic":"Question 8","question":"BBS の route・API・保存データの保護方針はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q8-o1","label":"閲覧・投稿・コメントをすべて public にする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o2","label":"閲覧は public、投稿・コメント・投票の API はログイン必須にする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o3","label":"閲覧は public、投稿者本人の編集削除 API とデータだけ保護する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o4","label":"閲覧・API・保存データをすべて auth only にする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q8-o5","label":"admin 面だけ保護し、一般の閲覧・投稿は public にする","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-8"},{"id":"q9","topic":"Question 9","question":"投稿・コメントの編集削除と状態遷移はどの範囲にしますか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q9-o1","label":"投稿後は変更不可、削除も今回は含めない","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o2","label":"本人が編集・削除でき、削除済み表示だけ持つ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o3","label":"本人が編集・論理削除でき、公開・非公開などの状態も持つ","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o4","label":"管理者による編集・削除・クローズまで含める","tradeoff":"選択後に設計判断として整理します。"},{"id":"q9-o5","label":"編集削除と状態遷移は後続対応にする","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-9"},{"id":"q10","topic":"Question 10","question":"初回実装で明確に対象外とするものはどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q10-o1","label":"認証・管理者機能・モデレーションは対象外","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o2","label":"通知・検索・外部連携は対象外","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o3","label":"画像・ファイル添付は対象外","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o4","label":"上記をすべて対象外にする","tradeoff":"選択後に設計判断として整理します。"},{"id":"q10-o5","label":"対象外は回答後の follow-up で決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-10"},{"id":"q11","topic":"Question 11","question":"Plan Mode で確定した主要フローの検証方法はどれですか？","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q11-o1","label":"既存 tooling があれば unit test と build/typecheck を中心に確認する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q11-o2","label":"投稿・コメント・投票・保存を unit test と e2e で確認する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q11-o3","label":"主要画面の e2e と保存結果の確認を優先する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q11-o4","label":"既存 tooling を調査してから最小の verify 系 script と検証範囲を決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-11"}]}],"openQuestions":[],"dataModelHandoffNotes":[]}','{"title":"BBS 初回仕様確認","questions":[{"text":"初回実装で優先する閲覧導線はどれですか？","type":"radio","options":["スレッド一覧から詳細・コメントへ進む最小構成","一覧と詳細を同一画面で確認する構成","一覧・詳細に加えてカテゴリ別の閲覧も含める"]},{"text":"初回実装に含める投稿単位はどれですか？","type":"radio","options":["スレッド投稿のみ","スレッド投稿とコメント返信","スレッド投稿・コメント返信・コメントへの返信"]},{"text":"投票機能の初期範囲はどれですか？","type":"radio","options":["今回は含めない","投稿への賛成票・反対票のみ","投稿とコメントへの賛成票・反対票","賛成票のみ"]},{"text":"一覧の並び替えと追加読み込みはどの範囲にしますか？","type":"radio","options":["新着順の固定表示のみ","新着順・人気順を切り替え、ページングする","新着順・人気順を切り替え、無限スクロールする","今回は一覧の並び替えを後続対応にする"]},{"text":"todolist の実装に使う技術スタックはどれですか？","type":"radio","options":["Hono + React/Vite","Python/FastAPI + React/Vite","API only","RAG を含む構成","既存構成を調査してから決める"]},{"text":"投稿・コメント・投票の保存先はどれですか？","type":"radio","options":["SQLite","PostgreSQL","PostgreSQL + pgvector","Turso/libSQL","DBなし・後続決定"]},{"text":"ユーザー、投稿、コメントのデータ所有境界はどれですか？","type":"radio","options":["ユーザー識別なしで、BBS 全体の共有データとして扱う","ユーザー識別を持ち、自分の投稿・コメントだけ編集削除できる","ユーザー識別を持ち、自分の投稿・コメントに加えて管理者操作も持つ","所有境界は後続の認証仕様と合わせて決める"]},{"text":"BBS の route・API・保存データの保護方針はどれですか？","type":"radio","options":["閲覧・投稿・コメントをすべて public にする","閲覧は public、投稿・コメント・投票の API はログイン必須にする","閲覧は public、投稿者本人の編集削除 API とデータだけ保護する","閲覧・API・保存データをすべて auth only にする","admin 面だけ保護し、一般の閲覧・投稿は public にする"]},{"text":"投稿・コメントの編集削除と状態遷移はどの範囲にしますか？","type":"radio","options":["投稿後は変更不可、削除も今回は含めない","本人が編集・削除でき、削除済み表示だけ持つ","本人が編集・論理削除でき、公開・非公開などの状態も持つ","管理者による編集・削除・クローズまで含める","編集削除と状態遷移は後続対応にする"]},{"text":"初回実装で明確に対象外とするものはどれですか？","type":"radio","options":["認証・管理者機能・モデレーションは対象外","通知・検索・外部連携は対象外","画像・ファイル添付は対象外","上記をすべて対象外にする","対象外は回答後の follow-up で決める"]},{"text":"Plan Mode で確定した主要フローの検証方法はどれですか？","type":"radio","options":["既存 tooling があれば unit test と build/typecheck を中心に確認する","投稿・コメント・投票・保存を unit test と e2e で確認する","主要画面の e2e と保存結果の確認を優先する","既存 tooling を調査してから最小の verify 系 script と検証範囲を決める"]}]}','valid');
